mapper.select:
SELECT
a.user_code AS usercode

FROM `yh_user_reginfo` AS a
LEFT JOIN `yh_user_make_card` AS b
ON a.user_code=b.user_code

LEFT JOIN `yh_user_enrolinfo` AS d
ON a.user_code=d.user_code
LEFT JOIN (
SELECT  g.`user_code`,g.age,
g.`meal_id`,
g.height,
g.weight,
g.strength,
g.record_kay,
f.max_chat_time record_data,
g.record_mode,
g.sex
FROM    `yh_food_srecipe_record` AS g
INNER JOIN
(
SELECT *, MAX(STR_TO_DATE( `record_data`, '%Y-%m-%d %H:%i:%s')) AS max_chat_time FROM yh_food_srecipe_record GROUP BY user_code
) AS f
ON g.`user_code`=f.user_code AND g.record_data=f.max_chat_time

GROUP BY g.user_code) AS c

ON c.user_code=a.user_code
LEFT JOIN `yh_food_srecipe` AS e
ON c.`meal_id`=e.`id`

WHERE b.doctor=(SELECT id FROM `yh_user_admin_info` WHERE user_code=#{usercode})



    and b.Org_Id=#{orgid}


    and  d.Flag_Dgroup LIKE CONCAT('%',#{groupid},'%')


    and   c.record_mode=#{mode}


    and c.sex=#{sex}


    and  c.strength=#{strength}



    and   c.age > #{ageStr}


    and  c.age < #{ageEnd}


    and c.height > #{heightStr}


    and c.height < #{heightEnd}



    and c.weight > #{weightStr}


    and  c.weight < #{weightEnd}



    and  c.record_kay > #{kayStr}


    and a.record_kay < #{kayEnd}



    and c.record_name LIKE CONCAT('%',#{recordname},'%')



    and a.name LIKE CONCAT('%',#{username},'%')

SELECT a.user_code AS usercode, a.name user_name, c.age, c.height, c.weight, c.strength, c.record_kay, c.record_data,
e.fs_describe AS record_name, d.Flag_Dgroup, c.record_mode, b.Org_Id, c.sex FROM `yh_user_reginfo` AS a LEFT JOIN `yh_user_make_card` AS b ON a.user_code=b.user_code
LEFT JOIN `yh_user_enrolinfo` AS d ON a.user_code=d.user_code LEFT JOIN ( SELECT g.`user_code`,g.age, g.`meal_id`, g.height, g.weight, g.strength, g.record_kay, f.record_data, g.record_mode, g.sex FROM `yh_food_srecipe_record` AS g INNER JOIN (SELECT t.*,a.max_chat_time FROM (SELECT user_code,MAX(record_id) AS max_chat_time FROM yh_food_srecipe_record GROUP BY user_code) a LEFT JOIN yh_food_srecipe_record t ON t.user_code=a.user_code AND t.record_id=a.max_chat_time) AS f ON g.`user_code` = f.user_code AND g.record_id = f.max_chat_time GROUP BY g.user_code) AS c
ON c.user_code=a.user_code LEFT JOIN `yh_food_srecipe` AS e ON c.`meal_id`=e.`id`
WHERE b.doctor=(SELECT id FROM `yh_user_admin_info` WHERE user_code=#{usercode})
and b.Org_Id=#{orgid}
and d.Flag_Dgroup LIKE CONCAT('%',#{groupid},'%')
and c.record_mode=#{mode}
and c.sex=#{sex}
and c.strength=#{strength}
and c.age > #{ageStr}
and c.age < #{ageEnd}
and c.height > #{heightStr}
and c.height < #{heightEnd}
and c.weight > #{weightStr}
and c.weight < #{weightEnd}
and c.record_kay > #{kayStr}
and a.record_kay < #{kayEnd}
and c.record_name LIKE CONCAT('%',#{recordname},'%')
and a.name LIKE CONCAT('%',#{username},'%')
ORDER BY c.record_data DESC,a.user_code
